//! WI-20260911-09E6M — A DOMAIN IS GENERATED BY SIZE, so a case with two recursive fields is
//! fair (kernel-language §5.3, proposal 060 §2.3).
//!
//! WI-743 bought fairness with ORDER alone — base constructors first, inside a case the
//! recursive fields first — which makes a chain come out by length and nothing more: a
//! depth-first search descends in the later of two infinite positions for ever, so
//! `node(l: Tree, r: Tree)` kept `l` at `leaf` and never reached `node(node(leaf, leaf), leaf)`.
//! No clause order makes a product of two infinite streams fair; the resolver now generates a
//! value in ROUNDS (`FrameState::SizeRounds`): round `k` asks the fill with a budget of `k` cases
//! with fields, admits only a branch that spent it all, and the stream ends after a round that
//! cut no member short. A nullary case, a primitive, a tuple and a bound part cost nothing.
//!
//! BACK-OUT, measured 2026-11-27 one axis at a time over this file and the domain suites
//! (`wi743`, `wi_yr3n7`, `wi_shed7`, `wi_sxz3g`, `wi_wt8wg`, `wi_5g28a`, `wi_hwd8a`), each a
//! temporary mutation in one build, removed:
//!  * [R] no rounds (the `apply_domain` lowering's rounds arm never taken) — every row here but
//!    `a_finite_domain_still_ends`, `wi743::two_recursive_positions_in_one_constructor_are_fair`
//!    and `wi_yr3n7::an_unbound_column_generates_by_size_then_in_declaration_order`.
//!    `inside_a_size_the_base_cases_come_first` fails there too: without rounds its base group
//!    comes out in declaration order, `one` before `none`;
//!  * [T] a tuple's fill opening no rounds of its own (`rounds: false` at the tuple arm) —
//!    `a_tuples_components_share_one_round` alone: each component then opens rounds of its
//!    own, the second's infinite inside the first's;
//!  * [A] adjacent typed columns not sharing the round (`step_size_rounds`' end placed right
//!    after the first fill) — `adjacent_typed_columns_share_one_round` alone;
//!  * [C] a cut leaving the rounds open (`apply_cut`'s `SizeRounds` arm removed) —
//!    `a_cut_closes_the_rounds` alone;
//!  * [P] the base-first partition removed (`fill_derive::emit_fill_clauses`' sort) —
//!    `inside_a_size_the_base_cases_come_first` alone. WI-743's row for it,
//!    `a_base_constructor_declared_last_is_still_tried_first`, passes: the rounds put `stop`
//!    first by size;
//!  * [F] the recursive fields not first inside a case — `wi743::an_infinite_domain_is_fair`,
//!    which asserts the first seven lists and not only their lengths since this ticket, and
//!    `the_holes_of_a_bound_value_share_one_round`, whose order inside a size it also decides.
//!
//! The controls pass under every axis: `a_finite_domain_still_ends` (a finite domain ends,
//! untruncated) and YR3N7's cost rows (a ground check costs per element what it did; the
//! rounds add a constant per column).

use anthill_core::kb::resolve::{ResolveConfig, ResolveStats};
use anthill_core::kb::term::{Term, Var};
use anthill_core::kb::KnowledgeBase;
use smallvec::SmallVec;

use crate::common::{load_kb_with, show_value};

const SRC: &str = r#"
namespace test.f09e6m
  import anthill.prelude.{Int64, List}
  sort Bit
    entity o
    entity i
  end
  sort Tree
    entity leaf
    entity node(l: Tree, r: Tree)
  end
  -- two INFINITE fields in a case that is no recursion of its sort's own
  sort Both
    entity both(a: List[T = Bit], b: List[T = Bit])
  end
  -- finite, with fields at two levels: the stream takes three rounds and ends
  sort Flag
    entity flag(on: Bit, off: Bit)
  end
  sort Pair2
    entity pair2(x: Flag, y: Flag)
  end
  -- the base-first partition as the order WITHIN a size: the recursive case declared first,
  -- beside a base case with a field, the two of size 1 each
  sort Seq
    entity more(next: Seq)
    entity one(c: Bit)
    entity none
  end
  rule trees(?x: Tree) :- true
  rule boths(?x: Both) :- true
  rule tuples(?x: (List[T = Bit], List[T = Bit])) :- true
  rule pairs(?x: Pair2) :- true
  rule seqs(?x: Seq) :- true
  -- two base cases, the BIGGER declared first: round 1 refuses `deep`'s flag for want of
  -- budget before it answers `shallow(o)`
  sort Deep
    entity deep(f: Flag)
    entity shallow(c: Bit)
  end
  rule deeps(?x: Deep) :- true
  rule first_deep(?x) :- deeps(?x), !
  rule holes(?x: List[T = Tree]) :- ?x <=> [?, ?]
  rule pair(a: Tree, b: Tree) :- true
  rule pairs_of_trees(?p) :- pair(?a, ?b), ?p <=> (?a, ?b)
end
"#;

/// The rows `test.f09e6m.<rel>(?x)` answers, each `?x` rendered, under `cap` answers (0 for
/// all) and with answer dedup `dedup` — OFF where a row says every member comes out ONCE, which
/// dedup would hide — and the search's stats.
fn rows_of(kb: &mut KnowledgeBase, rel: &str, cap: usize, dedup: bool) -> (Vec<String>, ResolveStats) {
    let f = kb
        .try_resolve_symbol(&format!("test.f09e6m.{rel}"))
        .unwrap_or_else(|| panic!("`{rel}` resolves"));
    let sym = kb.intern("x");
    let vid = kb.fresh_var(sym);
    let x = kb.alloc(Term::Var(Var::Global(vid)));
    let goal = kb.alloc(Term::Fn {
        functor: f,
        pos_args: SmallVec::from_elem(x, 1),
        named_args: SmallVec::new(),
    });
    let config = ResolveConfig {
        max_solutions: cap,
        dedup_answers: dedup,
        // Small, so a back-out that never ends stops in a second, and as a failure.
        max_steps: 400_000,
        ..Default::default()
    };
    let (sols, stats) = kb.resolve_with_stats(&[goal], &config);
    assert!(sols.iter().all(|s| s.is_definite()), "every row definite");
    let shown = sols
        .iter()
        .map(|s| {
            let v = kb.reify(x, &s.subst);
            show_value(kb, &v)
        })
        .collect();
    (shown, stats)
}

/// How many `node`s a rendered tree has — its size.
fn tree_size(shown: &str) -> usize {
    shown.matches("node(").count()
}

fn distinct(rows: &[String]) -> bool {
    let set: std::collections::HashSet<&String> = rows.iter().collect();
    set.len() == rows.len()
}

/// THE TICKET'S CASE, measured whole: a free `Tree` comes out BY SIZE, each tree ONCE — the
/// Catalan numbers 1, 1, 2, 5, 14 of trees with 0, 1, 2, 3, 4 nodes, with answer dedup off, so a
/// tree a later round generated again would show. The fourth row is
/// `node(node(leaf, leaf), leaf)`, which depth-first search never reached. FAILS under [R]: every
/// `l` is `leaf`.
#[test]
fn a_tree_comes_out_by_size_each_tree_once() {
    let mut kb = load_kb_with(SRC);
    let (rows, _) = rows_of(&mut kb, "trees", 23, false);
    let sizes: Vec<usize> = rows.iter().map(|r| tree_size(r)).collect();
    let mut want = vec![0, 1, 2, 2];
    want.extend([3; 5]);
    want.extend([4; 14]);
    assert_eq!(sizes, want, "{rows:#?}");
    assert!(distinct(&rows), "{rows:#?}");
    assert!(
        rows[3].starts_with("node(l: node("),
        "the left position leaves the base constructor in the round of size 2: {rows:#?}"
    );
}

/// Fairness is across the WHOLE value, not per recursion: `both(a: List, b: List)` is no
/// recursion of `Both`'s own, and its two infinite fields share one round — size 1 is
/// `both(nil, nil)`, size 2 puts one bit in either field, and size 3 starts with one in each.
/// FAILS under [R]: `a` stays `nil` while `b` runs through every list.
#[test]
fn two_infinite_fields_share_one_round() {
    let mut kb = load_kb_with(SRC);
    let (rows, _) = rows_of(&mut kb, "boths", 13, false);
    assert!(distinct(&rows), "{rows:#?}");
    assert_eq!(
        rows[..5],
        [
            "both(a: nil, b: nil)",
            "both(a: nil, b: [o])",
            "both(a: nil, b: [i])",
            "both(a: [o], b: nil)",
            "both(a: [i], b: nil)",
        ],
        "{rows:#?}"
    );
    assert_eq!(rows[9], "both(a: [o], b: [o])", "{rows:#?}");
}

/// A TUPLE costs nothing, and its components share its round: `(nil, nil)` is size 0, and the
/// first row with a bit in each component is the tenth. FAILS under [R] and under [T].
#[test]
fn a_tuples_components_share_one_round() {
    let mut kb = load_kb_with(SRC);
    let (rows, _) = rows_of(&mut kb, "tuples", 13, false);
    assert!(distinct(&rows), "{rows:#?}");
    assert_eq!(rows[0], "(nil, nil)", "{rows:#?}");
    assert_eq!(rows[9], "([o], [o])", "{rows:#?}");
}

/// A VALUE BOUND WITH HOLES has its holes generated in one round: the spine `[?, ?]` costs
/// nothing, and the two trees share the budget — the sixth row has a node in each. FAILS under
/// [R]: one hole stays `leaf` while the other runs through every tree.
#[test]
fn the_holes_of_a_bound_value_share_one_round() {
    let mut kb = load_kb_with(SRC);
    let (rows, _) = rows_of(&mut kb, "holes", 8, false);
    assert!(distinct(&rows), "{rows:#?}");
    assert_eq!(
        rows[..3],
        ["[leaf, leaf]", "[node(l: leaf, r: leaf), leaf]", "[leaf, node(l: leaf, r: leaf)]"],
        "{rows:#?}"
    );
    assert_eq!(rows[5], "[node(l: leaf, r: leaf), node(l: leaf, r: leaf)]", "{rows:#?}");
}

/// A CLAUSE'S TYPED COLUMNS share one round: `pair(a: Tree, b: Tree)` appends one fill per
/// column, and the round the first opens takes the second inside it. FAILS under [A] (the end
/// placed right after the first fill): `a` stays `leaf` while `b` runs through every tree.
#[test]
fn adjacent_typed_columns_share_one_round() {
    let mut kb = load_kb_with(SRC);
    let (rows, _) = rows_of(&mut kb, "pairs_of_trees", 8, false);
    assert!(distinct(&rows), "{rows:#?}");
    assert_eq!(rows[0], "(leaf, leaf)", "{rows:#?}");
    assert!(
        rows.iter().any(|r| r.starts_with("(node(") && !r.ends_with(", leaf)")),
        "a row with a node in both columns: {rows:#?}"
    );
}

/// THE CONTROL: a FINITE domain still ends — `Pair2` takes three rounds, its 16 members all in
/// the last, and the stream ends there, not truncated (a round past them cuts nothing short).
#[test]
fn a_finite_domain_still_ends() {
    let mut kb = load_kb_with(SRC);
    let (rows, stats) = rows_of(&mut kb, "pairs", 0, false);
    assert_eq!(rows.len(), 16, "{rows:#?}");
    assert!(distinct(&rows), "{rows:#?}");
    assert!(!stats.truncated, "{stats:?}");
}

/// THE ORDER INSIDE A SIZE is the derivation's: base constructors first. `more`, recursive,
/// is declared before `one`, and both are of size 1 — so `one(o)`, `one(i)` come before
/// `more(none)`. FAILS under [P].
#[test]
fn inside_a_size_the_base_cases_come_first() {
    let mut kb = load_kb_with(SRC);
    let (rows, _) = rows_of(&mut kb, "seqs", 4, false);
    assert_eq!(
        rows,
        vec!["none", "one(c: o)", "one(c: i)", "more(next: none)"],
        "{rows:#?}"
    );
}

/// A CUT COMMITS THE ROUNDS AWAY: `deeps(?x), !` answers once, `shallow(o)`, and the search
/// ends. The fixture is chosen so that the round that answers CUT A MEMBER SHORT before its
/// answer — `deep(f: ?)`, tried first, could not afford its flag — and so has a bigger round
/// after it: a cut also prunes the untried cases of the round it fires in, so a round that cut
/// nothing short before its answer ends whether or not the cut closes the rounds (`trees(?x), !`
/// does, and answers `leaf` once under [C] too). FAILS under [C]: round 2 answers `deep(…)`.
#[test]
fn a_cut_closes_the_rounds() {
    let mut kb = load_kb_with(SRC);
    let (rows, stats) = rows_of(&mut kb, "first_deep", 0, true);
    assert_eq!(rows, vec!["shallow(c: o)"], "{stats:?}");
    assert!(!stats.truncated, "{stats:?}");
}
